 function reportEntries(){
  const current=page();if(!current)return [];
  const ids=new Set([...current.kpis.map(([key])=>current.calc+'.'+key),...current.charts.flatMap(spec=>chartIds(spec).split(' ')),...(document.body.dataset.page==='incubatorio'?['eggUse.records']:[])]);
  return [...ids].map(id=>entries.get(id)).filter(Boolean);
 }
 function resolveIds(ids){
  const spec=page()?.charts.find(chart=>chartIds(chart)===ids);
  if(spec&&document.getElementById('card-'+spec.id)?.dataset.view==='lote'&&spec.lot)return (spec.calc||page().calc)+'.'+spec.lot.metric;
  return ids;
 }
